 addApplication(){const company=String(this.newApp.company||'').trim();const role=String(this.newApp.role||'').trim();if(!company||!role){this.trackerMessage='Company and role are required.';return;}let url='';const typedUrl=String(this.newApp.url||'').trim();if(typedUrl){try{const parsed=new URL(typedUrl);if(!['http:','https:'].includes(parsed.protocol)||!parsed.hostname){this.trackerMessage='Job link must be a valid HTTP or HTTPS URL.';return;}url=parsed.toString();}catch{this.trackerMessage='Job link must be a valid HTTP or HTTPS URL.';return;}}const key=(v:string)=>v.trim().toLocaleLowerCase();const duplicate=this.applications.some((old:any)=>url?String(old.url||'').trim()===url:!String(old.url||'').trim()&&key(String(old.company||''))===key(company)&&key(String(old.role||''))===key(role));if(duplicate){this.trackerMessage='This vacancy is already in your tracker.';return;}const app={...this.newApp,company,role,url,track:this.activeTrack,id:crypto.randomUUID()};const next=[app,...this.applications];try{localStorage.setItem('jobpilot-applications',JSON.stringify(next));this.applications=next;this.trackerMessage='Vacancy added to this browser tracker as '+app.status+'.';this.newApp={company:'',role:'',applicationDate:new Date().toISOString().slice(0,10),contact:'',contactStatus:'Not found',followUpDate:'',status:'Saved',url:''};}catch{this.trackerMessage='Browser storage failed; the vacancy was not added. Remove old tracker records or free storage and retry.';}}
