 safeHttpUrl(value:string){try{const parsed=new URL(String(value||'').trim());return ['http:','https:'].includes(parsed.protocol)&&parsed.hostname?parsed.href:'';}catch{return '';}}
 parseMasterSections(raw:string):{summary:string[];skills:string[];experience:string[];education:string[];projects:string[];certifications:string[];languages:string[];other:string[]}{const sections={summary:[] as string[],skills:[] as string[],experience:[] as string[],education:[] as string[],projects:[] as string[],certifications:[] as string[],languages:[] as string[],other:[] as string[]};let active:keyof typeof sections='other';const headings:[RegExp,keyof typeof sections][]=[[ /^(professional\s+)?summary$|^career\s+summary$|^profile$|^objective$/i,'summary'],[/^(technical\s+)?skills$|^core\s+skills$|^core\s+competencies$|^technical\s+expertise$|^technologies$/i,'skills'],[/^(professional\s+)?experience$|^work\s+experience$|^employment\s+history$|^career\s+history$/i,'experience'],[/^education$|^academic\s+qualifications?$|^qualifications$/i,'education'],[/^projects$|^key\s+projects$/i,'projects'],[/^certifications?$|^certificates$/i,'certifications'],[/^languages?$/i,'languages']];for(const rawLine of raw.split(/\r?\n/)){const line=rawLine.trim();if(!line)continue;const normalized=line.replace(/[:\s]+$/,'').replace(/^[#*\s]+/,'');const match=headings.find(([pattern])=>pattern.test(normalized));if(match){active=match[1];continue;}sections[active].push(line);}return sections;}
