 openPortalSearch(){const role=this.jobTitle||'Java Angular Full Stack Developer';const location=this.profile.location||'Delhi NCR India';let url='';if(this.portalName==='LinkedIn')url='https://www.linkedin.com/jobs/search/?keywords='+encodeURIComponent(role)+'&location='+encodeURIComponent(location);else if(this.portalName==='Indeed')url='https://www.indeed.com/jobs?q='+encodeURIComponent(role)+'&l='+encodeURIComponent(location);else {const domain=this.portalName==='Naukri'?'naukri.com':'instahyre.com';url='https://www.google.com/search?q='+encodeURIComponent('site:'+domain+' jobs '+role+' '+location);}window.open(url,'_blank','noopener');this.portalMessage=this.portalName+' search opened. Review the original listing and paste its exact URL here before saving.';}
